/* Khadija's World PWA.1 service worker. Generated by scripts/build-pwa.mjs. */
const PWA_VERSION = __PWA_VERSION__;
const PRECACHE_URLS = __PWA_PRECACHE__;
const RUNTIME_URLS = __PWA_RUNTIME__;

const CACHE_PREFIX = "khadijas-world-pwa-";
const SHELL_CACHE = `${CACHE_PREFIX}shell-${PWA_VERSION}`;
const RUNTIME_CACHE = `${CACHE_PREFIX}runtime-${PWA_VERSION}`;
const OFFLINE_FALLBACK = new URL("./offline.html", self.registration.scope).href;
const APP_SHELL = new URL("./", self.registration.scope).href;
const API_PATH_PREFIX = "/api/";
const WARM_BATCH_SIZE = 6;

const scopedUrl = (relativeUrl) => new URL(relativeUrl, self.registration.scope).href;
const scopedPrecache = PRECACHE_URLS.map(scopedUrl);
const scopedRuntime = RUNTIME_URLS.map(scopedUrl);

async function cacheCriticalAssets() {
  const cache = await caches.open(SHELL_CACHE);
  const criticalUrls = Array.from(new Set([APP_SHELL, ...scopedPrecache]));
  for (const url of criticalUrls) {
    const response = await fetch(url, { cache: "reload" });
    if (!response.ok) {
      throw new Error(`Could not precache ${url}: ${response.status}`);
    }
    await cache.put(url, response.clone());
  }
}

async function broadcast(message) {
  const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
  for (const client of windows) client.postMessage(message);
}

async function warmRuntimeCache() {
  const cache = await caches.open(RUNTIME_CACHE);
  let completed = 0;
  let failed = 0;

  await broadcast({
    type: "PWA_CACHE_PROGRESS",
    completed,
    failed,
    total: scopedRuntime.length,
    version: PWA_VERSION,
  });

  for (let index = 0; index < scopedRuntime.length; index += WARM_BATCH_SIZE) {
    const batch = scopedRuntime.slice(index, index + WARM_BATCH_SIZE);
    const results = await Promise.allSettled(batch.map(async (url) => {
      if (await cache.match(url)) return;
      const response = await fetch(url, { cache: "no-cache" });
      if (!response.ok) throw new Error(`Could not cache ${url}: ${response.status}`);
      await cache.put(url, response.clone());
    }));

    for (const result of results) {
      completed += 1;
      if (result.status === "rejected") failed += 1;
    }

    await broadcast({
      type: "PWA_CACHE_PROGRESS",
      completed,
      failed,
      total: scopedRuntime.length,
      version: PWA_VERSION,
    });
  }

  await broadcast({
    type: failed === 0 ? "PWA_CACHE_READY" : "PWA_CACHE_PARTIAL",
    completed,
    failed,
    total: scopedRuntime.length,
    version: PWA_VERSION,
  });
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok && new URL(request.url).origin === self.location.origin) {
    const cache = await caches.open(RUNTIME_CACHE);
    await cache.put(request, response.clone());
  }
  return response;
}

async function refreshAppShell(event, cache) {
  try {
    const preloaded = await event.preloadResponse;
    const response = preloaded || await fetch(event.request);
    if (!response.ok) return;
    await cache.put(APP_SHELL, response.clone());
  } catch {
    // The cached shell remains authoritative while offline.
  }
}

async function appShellNavigation(event) {
  const cache = await caches.open(SHELL_CACHE);
  const cached = (
    await cache.match(APP_SHELL)
    || await cache.match(scopedUrl("./index.html"))
  );

  if (cached) {
    event.waitUntil(refreshAppShell(event, cache));
    return cached;
  }

  try {
    const preloaded = await event.preloadResponse;
    const response = preloaded || await fetch(event.request);
    if (!response.ok) {
      throw new Error(`Navigation failed with ${response.status}`);
    }
    await cache.put(APP_SHELL, response.clone());
    return response;
  } catch {
    return (
      await caches.match(OFFLINE_FALLBACK)
      || new Response("Khadija's World is offline.", {
        status: 503,
        headers: { "Content-Type": "text/plain; charset=utf-8" },
      })
    );
  }
}

self.addEventListener("install", (event) => {
  event.waitUntil(cacheCriticalAssets());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    if (self.registration.navigationPreload) {
      await self.registration.navigationPreload.enable();
    }

    const cacheNames = await caches.keys();
    await Promise.all(cacheNames.map((cacheName) => {
      if (!cacheName.startsWith(CACHE_PREFIX)) return Promise.resolve(false);
      if (cacheName === SHELL_CACHE || cacheName === RUNTIME_CACHE) return Promise.resolve(false);
      return caches.delete(cacheName);
    }));

    await self.clients.claim();
    await broadcast({ type: "PWA_ACTIVE", version: PWA_VERSION });
  })());
});

self.addEventListener("message", (event) => {
  const message = event.data;
  if (!message || typeof message !== "object") return;

  if (message.type === "PWA_SKIP_WAITING") {
    self.skipWaiting();
    return;
  }

  if (message.type === "PWA_WARM_OFFLINE_CACHE") {
    event.waitUntil(warmRuntimeCache());
    return;
  }

  if (message.type === "PWA_GET_STATUS") {
    event.waitUntil((async () => {
      const cache = await caches.open(RUNTIME_CACHE);
      let runtimeCached = 0;
      for (const url of scopedRuntime) {
        if (await cache.match(url)) runtimeCached += 1;
      }
      event.source?.postMessage({
        type: "PWA_STATUS",
        version: PWA_VERSION,
        runtimeCached,
        runtimeTotal: scopedRuntime.length,
      });
    })());
  }
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (url.pathname.startsWith(API_PATH_PREFIX)) {
    event.respondWith(fetch(request));
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(appShellNavigation(event));
    return;
  }

  if (url.pathname.endsWith("/sw.js") || url.pathname.endsWith("/pwa-assets.json")) {
    event.respondWith(fetch(request, { cache: "no-store" }));
    return;
  }

  event.respondWith(cacheFirst(request));
});
